// === Tab: mySketch ===
let Shader;
const balls=[],num=15;
function preload(){
  Shader=getShader(this._renderer);
}
function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
	background(25);
	pixelDensity(1);
  noStroke();
	for (let i=0;i<num;i++) {
		let b={
			x:(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),
			y:(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),
			vx:0,
			vy:0,
			rad:1/sqrt(i+1)*20,
			r:random(),g:random(),b:random()
		}
		balls.push(b);
	}
}
function draw() {
	let data=[];
	let dataCol=[];
	balls[0].x=(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	balls[0].y=(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	for (let i=num-1;i>0;i--) {
		var b=balls[i];
		let a=atan2(balls[i-1].y-b.y,balls[i-1].x-b.x);
		b.vx+=cos(a)*sqrt((b.x-balls[i-1].x)**2+(b.y-balls[i-1].y)**2)/100;
		b.vy+=sin(a)*sqrt((b.x-balls[i-1].x)**2+(b.y-balls[i-1].y)**2)/100;
		b.vx*=0.9;
		b.vy*=0.9;
		b.x+=b.vx;
		b.y+=b.vy;
	}
	for (let b of balls) {
		if (b.x<			 b.rad) {b.x=			 b.rad;b.vx*=-1;}
		if (b.x>width -b.rad) {b.x=width -b.rad;b.vx*=-1;}
		if (b.y<			 b.rad) {b.y=			 b.rad;b.vy*=-1;}
		if (b.y>height-b.rad) {b.y=height-b.rad;b.vy*=-1;}
		data.push(b.x,b.y,int(b.rad*10));
		dataCol.push(b.r,b.g,b.b);
	}
  shader(Shader);
	Shader.setUniform("balls",data);
	Shader.setUniform("ballsCol",dataCol);
  rect(0,0,width,height);
}
function getShader(_renderer) {
	const vert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord = aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position = positionVec4;
		}
	`;
	const frag = `
		precision highp float;
		varying vec2 vTexCoord;
		const float WIDTH=${windowWidth}.;
		const float HEIGHT=${windowHeight}.;
		uniform vec3 balls[${num}];
		uniform vec3 ballsCol[${num}];
		void main() {
			float x=vTexCoord.x*WIDTH;
			float y=HEIGHT-vTexCoord.y*HEIGHT;
			vec3 col=vec3(0.);
			for (int i=0;i<${num};i++) {
				vec3 b=balls[i];
				float r=b.z/10.;
				col.x+=r*r/((b.x-x)*(b.x-x)+(b.y-y)*(b.y-y))*ballsCol[i].x;
				col.y+=r*r/((b.x-x)*(b.x-x)+(b.y-y)*(b.y-y))*ballsCol[i].y;
				col.z+=r*r/((b.x-x)*(b.x-x)+(b.y-y)*(b.y-y))*ballsCol[i].z;
			}
			col=sqrt(col);
			gl_FragColor = vec4(col,1.);
		}
	`;
	return createShader(vert, frag);
}

